"use client";

import * as React from "react";
import { cn } from "@/lib/utils";
import { prefersReducedMotion } from "@/lib/motion/gsap";

/**
 * DispatchFilm — the cinematic beat of the home page. A 120-frame film of one
 * real request (message -> four-agent handoff -> technician route -> AC fixed)
 * that scrubs with the scroll position, like an Apple product reel.
 *
 * Frames live in /public/frames/dispatch/fNNN.webp (generated by
 * scripts/film/render.mjs, or swap in real footage via scripts/video-to-frames.mjs).
 * The section is `position: sticky` inside a tall wrapper — no scroll-jacking, no
 * pin library, nothing that can trap the page. Under reduced motion it renders the
 * poster and the four beats as plain stacked content.
 */

const FRAME_COUNT = 120;
const frameSrc = (i: number) => `/frames/dispatch/f${String(i + 1).padStart(3, "0")}.webp`;

// Portrait screens can't fit the 16:9 frame legibly, so they zoom into a 760px-wide window of
// it and pan along the story: phone -> each agent in turn -> the route -> the finished job.
const FOCUS: [number, number][] = [
  [0, 640], [0.29, 640], [0.37, 330], [0.44, 330], [0.53, 610], [0.62, 890],
  [0.67, 890], [0.74, 300], [0.88, 880], [1, 880],
];
const focusAt = (p: number) => {
  for (let i = 0; i < FOCUS.length - 1; i++) {
    const [p0, x0] = FOCUS[i];
    const [p1, x1] = FOCUS[i + 1];
    if (p <= p1) return x0 + ((x1 - x0) * (p - p0)) / Math.max(p1 - p0, 1e-6);
  }
  return FOCUS[FOCUS.length - 1][1];
};

const BEATS = [
  {
    from: 0,
    to: 0.29,
    n: "01",
    title: "You say it, the way you'd say it to a neighbour.",
    body: "Roman Urdu, Urdu or English. No forms, no category menus — just the problem, the area and the time.",
  },
  {
    from: 0.29,
    to: 0.67,
    n: "02",
    title: "Four agents hand the job along. Nobody guesses.",
    body: "Concierge triages, Discovery finds real verified providers, Booking locks the slot, Followup checks in afterwards. Every step is logged and visible to you.",
  },
  {
    from: 0.67,
    to: 0.86,
    n: "03",
    title: "You see the person, the rate and the ETA first.",
    body: "Their rating, their price and when they arrive — before anything is confirmed.",
  },
  {
    from: 0.86,
    to: 1.01,
    n: "04",
    title: "Fixed, rated, followed up.",
    body: "The job closes with a confirmation code, a rating, and a check-in on how it went.",
  },
] as const;

export function DispatchFilm() {
  const wrapRef = React.useRef<HTMLDivElement>(null);
  const canvasRef = React.useRef<HTMLCanvasElement>(null);
  const framesRef = React.useRef<(HTMLImageElement | null)[]>(Array(FRAME_COUNT).fill(null));
  const [reduced, setReduced] = React.useState(false);
  const [progress, setProgress] = React.useState(0);
  const [loaded, setLoaded] = React.useState(0);
  const [surround, setSurround] = React.useState("#17100B");
  const surroundRef = React.useRef("#17100B");

  // --- preload: first frame immediately, the rest in the background ---------
  React.useEffect(() => {
    const rm = prefersReducedMotion();
    setReduced(rm);
    if (rm) return;
    let cancelled = false;
    let count = 0;
    const load = (i: number) =>
      new Promise<void>((resolve) => {
        const img = new Image();
        img.decoding = "async";
        img.onload = () => {
          if (cancelled) return resolve();
          framesRef.current[i] = img;
          count += 1;
          if (count % 6 === 0 || count === FRAME_COUNT) setLoaded(count);
          resolve();
        };
        img.onerror = () => resolve();
        img.src = frameSrc(i);
      });
    (async () => {
      await load(0);
      // spread loading so scrubbing works at any scroll position quickly
      const order = [FRAME_COUNT - 1, 60, 30, 90, 15, 45, 75, 105];
      await Promise.all(order.map(load));
      for (let i = 1; i < FRAME_COUNT; i += 8) {
        const batch: Promise<void>[] = [];
        for (let k = i; k < Math.min(i + 8, FRAME_COUNT); k++) if (!framesRef.current[k]) batch.push(load(k));
        await Promise.all(batch);
        if (cancelled) return;
      }
    })();
    return () => {
      cancelled = true;
    };
  }, []);

  // --- draw: nearest loaded frame, contain-fit, DPR aware -------------------
  const draw = React.useCallback((p: number) => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;
    const target = Math.round(p * (FRAME_COUNT - 1));
    let img: HTMLImageElement | null = null;
    for (let d = 0; d < FRAME_COUNT && !img; d++) {
      img = framesRef.current[target - d] ?? framesRef.current[target + d] ?? null;
    }
    if (!img) return;
    const { width: cw, height: ch } = canvas;
    ctx.fillStyle = surroundRef.current;
    ctx.fillRect(0, 0, cw, ch);
    let w: number;
    let h: number;
    if (cw / ch < 1.1) {
      // portrait: zoom into a window of the frame that follows the story
      const winW = Math.min(760, img.naturalWidth);
      const sx = Math.min(Math.max(focusAt(p) - winW / 2, 0), img.naturalWidth - winW);
      const scale = cw / winW;
      w = cw;
      h = img.naturalHeight * scale;
      ctx.drawImage(img, sx, 0, winW, img.naturalHeight, 0, (ch - h) / 2, w, h);
    } else {
      const scale = Math.min(cw / img.naturalWidth, ch / img.naturalHeight);
      w = img.naturalWidth * scale;
      h = img.naturalHeight * scale;
      ctx.drawImage(img, (cw - w) / 2, (ch - h) / 2, w, h);
    }
    if (surroundRef.current === "#17100B") {
      // Lossy WebP shifts the flat background a hair; match the surround to the frame's real
      // background (median of a few edge samples, so a stray dot-grid pixel can't skew it).
      try {
        const x0 = Math.max(0, Math.floor((cw - w) / 2)) + 10;
        const samples = [0.2, 0.35, 0.5, 0.65, 0.8].map((f) => ctx.getImageData(x0, Math.floor(ch * f), 1, 1).data);
        const med = (i: number) => [...samples.map((d) => d[i])].sort((a, b) => a - b)[2];
        const hex = `#${[med(0), med(1), med(2)].map((v) => v.toString(16).padStart(2, "0")).join("")}`;
        surroundRef.current = hex;
        setSurround(hex);
        draw(p); // repaint with the matched surround
      } catch {
        /* canvas read blocked — keep the default */
      }
    }
  }, []);

  // --- scroll -> progress (eased towards target so scrubbing feels fluid) ---
  React.useEffect(() => {
    if (reduced) return;
    const canvas = canvasRef.current;
    const wrap = wrapRef.current;
    if (!canvas || !wrap) return;

    const resize = () => {
      const dpr = Math.min(window.devicePixelRatio || 1, 2);
      const r = canvas.getBoundingClientRect();
      canvas.width = Math.round(r.width * dpr);
      canvas.height = Math.round(r.height * dpr);
      lastDrawn = -1;
      draw(current);
    };

    let target = 0;
    let current = 0;
    let raf = 0;
    let lastDrawn = -1;
    const readTarget = () => {
      const r = wrap.getBoundingClientRect();
      const total = r.height - (window.innerHeight - 56);
      target = total > 0 ? Math.min(1, Math.max(0, -r.top / total)) : 0;
    };
    let last = performance.now();
    const tick = () => {
      const now = performance.now();
      const k = 1 - Math.exp(-(now - last) / 90); // frame-rate independent ease
      last = now;
      current += (target - current) * k;
      if (Math.abs(target - current) < 0.0004) current = target;
      if (current !== lastDrawn) {
        lastDrawn = current;
        draw(current);
        setProgress((prev) => (Math.abs(prev - current) > 0.003 ? current : prev));
      }
      raf = requestAnimationFrame(tick);
    };

    readTarget();
    current = target;
    resize();
    window.addEventListener("scroll", readTarget, { passive: true });
    const onResize = () => {
      readTarget();
      resize();
    };
    window.addEventListener("resize", onResize);
    raf = requestAnimationFrame(tick);
    return () => {
      cancelAnimationFrame(raf);
      window.removeEventListener("scroll", readTarget);
      window.removeEventListener("resize", onResize);
    };
  }, [reduced, draw]);

  // redraw once the first frame lands (the effect above may run before it)
  React.useEffect(() => {
    draw(progress);
  }, [loaded]); // eslint-disable-line react-hooks/exhaustive-deps

  const beat = BEATS.find((b) => progress >= b.from && progress < b.to) ?? BEATS[0];

  if (reduced) {
    return (
      <section id="film" data-theme="marketing" className="bg-surface text-ink" aria-labelledby="film-title">
        <div className="mx-auto max-w-5xl px-4 py-20 sm:px-6">
          <h2 id="film-title" className="font-display text-3xl font-semibold sm:text-5xl">
            One request, start to finish.
          </h2>
          {/* eslint-disable-next-line @next/next/no-img-element */}
          <img src="/frames/dispatch-poster.webp" alt="A booked, completed home-repair job" className="mt-8 w-full rounded-lg" />
          <ol className="mt-10 grid gap-6 sm:grid-cols-2">
            {BEATS.map((b) => (
              <li key={b.n}>
                <p className="font-mono text-xs tracking-[0.2em] text-accent">{b.n}</p>
                <h3 className="font-display mt-1 text-xl font-semibold">{b.title}</h3>
                <p className="mt-2 text-ink-muted">{b.body}</p>
              </li>
            ))}
          </ol>
        </div>
      </section>
    );
  }

  return (
    <section id="film" data-theme="marketing" className="bg-surface text-ink" aria-labelledby="film-title">
      <h2 id="film-title" className="sr-only">
        One request, start to finish
      </h2>
      <div ref={wrapRef} className="relative" style={{ height: "460vh" }}>
        <div className="sticky top-14 flex h-[calc(100vh-3.5rem)] flex-col overflow-hidden" style={{ backgroundColor: surround }}>
          <canvas
            ref={canvasRef}
            role="img"
            aria-label="Animated walkthrough: a customer's message is handed through four agents, a technician is dispatched and the repair is completed."
            className="min-h-0 w-full flex-1"
          />

          {/* caption bar — solid surface, not a gradient scrim */}
          <div className="relative border-t border-hairline bg-surface px-4 py-5 sm:px-8 sm:py-6">
            <div className="mx-auto flex max-w-6xl flex-col gap-4 md:flex-row md:items-end md:justify-between">
              <div key={beat.n} className="max-w-2xl animate-in fade-in slide-in-from-bottom-2 duration-300">
                <p className="font-mono text-xs tracking-[0.2em] text-accent">STEP {beat.n} / 04</p>
                <h3 className="font-display mt-1 text-xl font-semibold leading-tight sm:text-3xl">{beat.title}</h3>
                <p className="mt-2 max-w-xl text-sm text-ink-muted sm:text-base">{beat.body}</p>
              </div>
              <ol className="flex shrink-0 items-center gap-2" aria-hidden>
                {BEATS.map((b) => (
                  <li
                    key={b.n}
                    className={cn(
                      "h-1.5 w-10 rounded-pill transition-colors sm:w-14",
                      progress >= b.from ? "bg-accent" : "bg-hairline",
                    )}
                  />
                ))}
              </ol>
            </div>
          </div>
        </div>
      </div>
    </section>
  );
}
